input.old_string:
:root {
  --bg: #fff;
  --fg: #111;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #111;
    --fg: #eee;
  }
}
body {
  min-height: 100vh;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: var(--bg);
  color: var(--fg);
}
svg {
  display: block;
  width: min(400px, 100%);
  height: auto;
}

input.new_string:
:root {
  --bg: #fff;
  --fg: #2563eb;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #111;
    --fg: #60a5fa;
  }
}
body {
  min-height: 100vh;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: var(--bg);
  color: var(--fg);
}
svg {
  display: block;
  width: min(400px, 100%);
  height: auto;
  filter: drop-shadow(0 4px 12px rgba(0, 0, 0, 0.15));
}
circle {
  transition: transform 0.2s ease;
  transform-origin: center;
}
@media (prefers-reduced-motion: no-preference) {
  svg:hover circle {
    transform: scale(1.03);
  }
}

